 1	method Tangent(r: array<int>, x: array<int>) returns (b: bool)
 2	    requires forall i, j :: 0 <= i <= j < x.Length ==> x[i] <= x[j] // values in x will be in ascending order or empty
 3	    requires forall i, j :: (0 <= i < r.Length && 0 <= j < x.Length) ==> (r[i] >= 0 && x[j] >= 0)       // x and r will contain no negative values
 4	    ensures !b ==> forall i, j :: 0 <= i< r.Length && 0 <= j < x.Length ==> r[i] != x[j]   
 5	    ensures b ==> exists i, j :: 0 <= i< r.Length && 0 <= j < (x.Length) - 1 && r[i] == x[j]
 6	{
 7	    var tempB, tangentMissing, k, l := false, false, 0, 0;
 8	    while k != r.Length && !tempB
 9	        invariant 0 <= k <= r.Length
10	        invariant tempB ==> exists i, j :: 0 <= i < r.Length && 0 <= j < x.Length && r[i] == x[j]
11	        invariant !tempB ==> forall i, j :: (0 <= i<k && 0 <= j < x.Length) ==> r[i] != x[j]
12	        decreases r.Length - k
13	    {
14	        l:= 0;
15	        tangentMissing := false;
16	        while l != x.Length && !tangentMissing
17	            invariant 0 <= l <= x.Length
18	            invariant tempB ==> exists i, j :: 0 <= i < r.Length && 0 <= j < x.Length && r[i] == x[j]
19	            invariant !tempB ==> forall i :: 0 <= i< l ==> r[k] != x[i]
20	            invariant tangentMissing ==> forall i :: (l <= i < x.Length) ==> r[k] != x[i]
21	            decreases x.Length - l, !tempB, !tangentMissing
22	        {
23	
24	            if  r[k] == x[l] {
25	                tempB := true;
26	            }
27	            if (r[k] < x[l]) {
28	                tangentMissing := true;
29	            }
30	            l := l + 1;
31	        }
32	        k := k + 1;
33	    }
34	    b := tempB;
35	}

